-- 015_demo_slimming: remove cancelled business capabilities and regroup administration.
-- Historical answers, review events and source snapshots must pass the runner's read-only preflight.
-- Existing migration files stay immutable; successor checks describe the final supported shape.

-- @step remove_retired_question_dictionary
-- @replaces-check 004_system/seed_fixed_dictionaries
-- @check SELECT CASE WHEN (SELECT COUNT(*) FROM `sys_dictionary` WHERE `is_system` = 1 AND (`type`, `code`, `label`, `sort`, `status`, `is_system`, `remark`) IN (('learner_source','institution','本机构学员',10,1,1,'业务固定枚举'),('learner_source','external','外来学员',20,1,1,'业务固定枚举'),('difficulty','easy','初级',10,1,1,'业务固定枚举'),('difficulty','medium','中级',20,1,1,'业务固定枚举'),('difficulty','hard','高级',30,1,1,'业务固定枚举'),('question_type','single','单选题',10,1,1,'业务固定枚举'),('question_type','multiple','多选题',20,1,1,'业务固定枚举'),('question_type','judgment','判断题',30,1,1,'业务固定枚举'),('regulation_status','draft','草稿',10,1,1,'业务固定枚举'),('regulation_status','published','已发布',20,1,1,'业务固定枚举'),('regulation_status','archived','已归档',30,1,1,'业务固定枚举'),('paper_status','draft','草稿',10,1,1,'业务固定枚举'),('paper_status','published','已发布',20,1,1,'业务固定枚举'),('paper_status','archived','已归档',30,1,1,'业务固定枚举'),('question_status','pending','待审核',10,1,1,'业务固定枚举'),('question_status','approved','已通过',20,1,1,'业务固定枚举'),('question_status','rejected','已驳回',30,1,1,'业务固定枚举'),('exam_status','in_progress','进行中',10,1,1,'业务固定枚举'),('exam_status','submitted','已交卷',20,1,1,'业务固定枚举'),('exam_status','passed','已通过',30,1,1,'业务固定枚举'),('exam_status','failed','未通过',40,1,1,'业务固定枚举'),('exam_status','timeout','超时交卷',50,1,1,'业务固定枚举'))) = 22 AND (SELECT COUNT(*) FROM sys_dictionary WHERE type='question_type' AND code='image')=0 THEN 1 ELSE 0 END AS complete;
DELETE FROM sys_dictionary WHERE type='question_type' AND code='image';

-- @step remove_retired_role_permissions
-- @check SELECT CASE WHEN (SELECT COUNT(*) FROM sys_role_permission WHERE permission_id IN (SELECT id FROM sys_permission WHERE code IN ('departments:read','departments:write','regulations:read','regulations:write','regulations:publish','exam_records:monitor','exam_records:review'))) = 0 THEN 1 ELSE 0 END AS complete;
DELETE FROM sys_role_permission WHERE permission_id IN (SELECT id FROM sys_permission WHERE code IN ('departments:read','departments:write','regulations:read','regulations:write','regulations:publish','exam_records:monitor','exam_records:review'));

-- @step remove_retired_permissions
-- @replaces-check 013_exam_monitor_navigation/register_exam_record_permissions
-- @check SELECT CASE WHEN (SELECT COUNT(*) FROM sys_permission WHERE code IN ('departments:read','departments:write','regulations:read','regulations:write','regulations:publish','exam_records:monitor','exam_records:review')) = 0 AND (SELECT COUNT(*) FROM sys_permission WHERE code='exam_records:read') = 1 THEN 1 ELSE 0 END AS complete;
DELETE FROM sys_permission WHERE code IN ('departments:read','departments:write','regulations:read','regulations:write','regulations:publish','exam_records:monitor','exam_records:review');

-- @step confirm_review_permission_removed
-- @replaces-check 011_manual_grading/register_exam_review_permission
-- @check SELECT CASE WHEN (SELECT COUNT(*) FROM sys_permission WHERE code='exam_records:review') = 0 THEN 1 ELSE 0 END AS complete;
DELETE FROM sys_permission WHERE code='exam_records:review';

-- @step remove_retired_management_menus
-- @replaces-check 004_system/seed_registered_menus
-- @check SELECT CASE WHEN (SELECT COUNT(*) FROM sys_menu WHERE route_path IN ('/admin/regulations','/admin/users','/admin/departments')) = 0 AND (SELECT COUNT(*) FROM sys_menu WHERE id IN (1,2,11,12,13,16,17,18,20,21,22,23,24,25,26)) = 15 THEN 1 ELSE 0 END AS complete;
DELETE FROM sys_menu WHERE route_path IN ('/admin/regulations','/admin/users','/admin/departments');

-- @step remove_grading_menu
-- @replaces-check 011_manual_grading/register_grading_menu
-- @check SELECT CASE WHEN (SELECT COUNT(*) FROM sys_menu WHERE route_path='/admin/grading') = 0 THEN 1 ELSE 0 END AS complete;
DELETE FROM sys_menu WHERE route_path='/admin/grading';

-- @step remove_monitor_menu
-- @replaces-check 013_exam_monitor_navigation/register_exam_monitor_menu
-- @check SELECT CASE WHEN (SELECT COUNT(*) FROM sys_menu WHERE route_path='/admin/exam-monitor') = 0 THEN 1 ELSE 0 END AS complete;
DELETE FROM sys_menu WHERE route_path='/admin/exam-monitor';

-- @step rename_retained_directories
-- @check SELECT CASE WHEN (SELECT COUNT(*) FROM sys_menu WHERE id=1 AND name='培训管理' AND type='directory' AND parent_id IS NULL AND sort=20 OR id=2 AND name='系统设置' AND type='directory' AND parent_id IS NULL AND sort=50) = 2 THEN 1 ELSE 0 END AS complete;
UPDATE sys_menu SET name=CASE id WHEN 1 THEN '培训管理' ELSE '系统设置' END, sort=CASE id WHEN 1 THEN 20 ELSE 50 END WHERE id IN (1,2) AND type='directory';

-- @step create_exam_directory
-- @check SELECT CASE WHEN (SELECT COUNT(*) FROM sys_menu WHERE name='考试管理' AND type='directory' AND parent_id IS NULL) = 1 THEN 1 ELSE 0 END AS complete;
INSERT IGNORE INTO sys_menu (parent_id,name,type,route_path,permission_code,icon,sort,status) SELECT NULL,'考试管理','directory',NULL,NULL,'Tickets',30,1 WHERE NOT EXISTS (SELECT 1 FROM sys_menu WHERE name='考试管理' AND type='directory' AND parent_id IS NULL);

-- @step group_exam_pages
-- @replaces-check 013_exam_monitor_navigation/register_exam_records_menu
-- @check SELECT CASE WHEN (SELECT COUNT(*) FROM sys_menu WHERE parent_id IN (SELECT id FROM sys_menu WHERE name='考试管理' AND type='directory' AND parent_id IS NULL) AND ((route_path='/admin/questions' AND name='题库管理' AND sort=10) OR (route_path='/admin/papers' AND sort=20) OR (route_path='/admin/exam-records' AND permission_code='exam_records:read' AND sort=30))) = 3 THEN 1 ELSE 0 END AS complete;
UPDATE sys_menu SET parent_id=(SELECT id FROM (SELECT id FROM sys_menu WHERE name='考试管理' AND type='directory' AND parent_id IS NULL LIMIT 1) AS selected_group), name=CASE route_path WHEN '/admin/questions' THEN '题库管理' ELSE name END, sort=CASE route_path WHEN '/admin/questions' THEN 10 WHEN '/admin/papers' THEN 20 ELSE 30 END WHERE route_path IN ('/admin/questions','/admin/papers','/admin/exam-records');

-- @step group_training_pages
-- @check SELECT CASE WHEN (SELECT COUNT(*) FROM sys_menu WHERE parent_id=1 AND ((route_path='/admin/training-categories' AND sort=10) OR (route_path='/admin/students' AND sort=20) OR (route_path='/admin/courses' AND sort=30))) = 3 THEN 1 ELSE 0 END AS complete;
UPDATE sys_menu SET parent_id=1, sort=CASE route_path WHEN '/admin/training-categories' THEN 10 WHEN '/admin/students' THEN 20 ELSE 30 END WHERE route_path IN ('/admin/training-categories','/admin/students','/admin/courses');

-- @step group_system_pages
-- @check SELECT CASE WHEN (SELECT COUNT(*) FROM sys_menu WHERE parent_id=2 AND route_path IN ('/admin/ai-config','/admin/administrators','/admin/roles','/admin/system/site-settings','/admin/system/dictionaries','/admin/system/menus','/admin/sessions','/admin/system/audit-logs')) = 8 THEN 1 ELSE 0 END AS complete;
UPDATE sys_menu SET parent_id=2, sort=CASE WHEN route_path='/admin/ai-config' AND sort=90 THEN 10 WHEN route_path='/admin/administrators' AND sort=10 THEN 20 WHEN route_path='/admin/roles' AND sort=20 THEN 30 WHEN route_path='/admin/system/site-settings' AND sort=60 THEN 40 WHEN route_path='/admin/system/dictionaries' AND sort=50 THEN 50 WHEN route_path='/admin/system/menus' AND sort=40 THEN 60 WHEN route_path='/admin/sessions' AND sort=30 THEN 70 WHEN route_path='/admin/system/audit-logs' AND sort=70 THEN 80 ELSE sort END WHERE route_path IN ('/admin/ai-config','/admin/administrators','/admin/roles','/admin/system/site-settings','/admin/system/dictionaries','/admin/system/menus','/admin/sessions','/admin/system/audit-logs');

-- @step root_dashboard
-- @replaces-check 014_training_statistics_navigation/register_admin_dashboard_menu
-- @check SELECT CASE WHEN (SELECT COUNT(*) FROM sys_menu WHERE route_path='/admin/dashboard' AND parent_id IS NULL AND type='menu' AND sort=10) = 1 THEN 1 ELSE 0 END AS complete;
UPDATE sys_menu SET parent_id=NULL, sort=10 WHERE route_path='/admin/dashboard';

-- @step root_statistics
-- @replaces-check 014_training_statistics_navigation/register_training_statistics_menu
-- @check SELECT CASE WHEN (SELECT COUNT(*) FROM sys_menu WHERE route_path='/admin/training-statistics' AND name='统计分析' AND parent_id IS NULL AND type='menu' AND sort=40) = 1 THEN 1 ELSE 0 END AS complete;
UPDATE sys_menu SET parent_id=NULL, name='统计分析', sort=40 WHERE route_path='/admin/training-statistics';

-- @step hide_legacy_statistics
-- @check SELECT CASE WHEN (SELECT COUNT(*) FROM sys_menu WHERE route_path='/admin/statistics' AND status<>0) = 0 THEN 1 ELSE 0 END AS complete;
UPDATE sys_menu SET status=0 WHERE route_path='/admin/statistics';

-- @step drop_empty_review_events
-- @replaces-check 011_manual_grading/create_exam_review_event
-- @check SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM INFORMATION_SCHEMA.TABLES WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='exam_review_event') THEN 1 ELSE 0 END AS complete;
DROP TABLE IF EXISTS exam_review_event;

-- @step remove_question_rubric
-- @replaces-check 007_question_bank/extend_question_identity
-- @check SELECT CASE WHEN (SELECT COUNT(*) FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'question') = 18 AND (SELECT COUNT(*) FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'question' AND ((COLUMN_NAME IN ('regulation_id', 'version_id', 'category_id', 'concept_id', 'current_version_id') AND DATA_TYPE = 'bigint' AND COLUMN_TYPE = 'bigint unsigned' AND IS_NULLABLE = 'YES' AND COLUMN_DEFAULT IS NULL) OR (COLUMN_NAME = 'difficulty' AND DATA_TYPE = 'varchar' AND COLUMN_TYPE = 'varchar(16)' AND IS_NULLABLE = 'YES' AND COLUMN_DEFAULT IS NULL) OR (COLUMN_NAME IN ('type', 'source') AND DATA_TYPE = 'varchar' AND COLUMN_TYPE = 'varchar(16)' AND IS_NULLABLE = 'NO') OR (COLUMN_NAME = 'score' AND COLUMN_TYPE = 'decimal(5,2)' AND IS_NULLABLE = 'NO' AND COLUMN_COMMENT = '题库建议分值；考试实际分值另存'))) = 9 AND (SELECT COUNT(*) FROM INFORMATION_SCHEMA.STATISTICS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'question' AND ((INDEX_NAME = 'idx_question_category_pool' AND NON_UNIQUE = 1 AND SEQ_IN_INDEX = 1 AND COLUMN_NAME = 'category_id' AND INDEX_TYPE = 'BTREE' AND SUB_PART IS NULL) OR (INDEX_NAME = 'idx_question_category_pool' AND NON_UNIQUE = 1 AND SEQ_IN_INDEX = 2 AND COLUMN_NAME = 'status' AND INDEX_TYPE = 'BTREE' AND SUB_PART IS NULL) OR (INDEX_NAME = 'idx_question_category_pool' AND NON_UNIQUE = 1 AND SEQ_IN_INDEX = 3 AND COLUMN_NAME = 'type' AND INDEX_TYPE = 'BTREE' AND SUB_PART IS NULL) OR (INDEX_NAME = 'idx_question_category_pool' AND NON_UNIQUE = 1 AND SEQ_IN_INDEX = 4 AND COLUMN_NAME = 'difficulty' AND INDEX_TYPE = 'BTREE' AND SUB_PART IS NULL) OR (INDEX_NAME = 'idx_question_concept' AND NON_UNIQUE = 1 AND SEQ_IN_INDEX = 1 AND COLUMN_NAME = 'concept_id' AND INDEX_TYPE = 'BTREE' AND SUB_PART IS NULL) OR (INDEX_NAME = 'idx_question_current_version' AND NON_UNIQUE = 1 AND SEQ_IN_INDEX = 1 AND COLUMN_NAME = 'current_version_id' AND INDEX_TYPE = 'BTREE' AND SUB_PART IS NULL))) = 6 AND (SELECT COUNT(*) FROM INFORMATION_SCHEMA.STATISTICS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'question' AND INDEX_NAME = 'idx_question_category_pool') = 4 AND (SELECT COUNT(*) FROM INFORMATION_SCHEMA.STATISTICS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'question' AND INDEX_NAME = 'idx_question_concept') = 1 AND (SELECT COUNT(*) FROM INFORMATION_SCHEMA.STATISTICS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'question' AND INDEX_NAME = 'idx_question_current_version') = 1 THEN 1 ELSE 0 END AS complete;
ALTER TABLE question DROP COLUMN rubric, MODIFY COLUMN type VARCHAR(16) NOT NULL COMMENT 'single / multiple / judgment';

-- @step remove_version_rubric
-- @replaces-check 007_question_bank/create_question_version
-- @check SELECT CASE WHEN EXISTS (SELECT 1 FROM INFORMATION_SCHEMA.TABLES WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'question_version' AND TABLE_TYPE = 'BASE TABLE' AND ENGINE = 'InnoDB' AND TABLE_COLLATION = 'utf8mb4_0900_ai_ci') AND (SELECT COUNT(*) FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'question_version') = 27 AND (SELECT COUNT(*) FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'question_version' AND ((COLUMN_NAME = 'id' AND DATA_TYPE = 'bigint' AND COLUMN_TYPE = 'bigint unsigned' AND IS_NULLABLE = 'NO' AND COLUMN_DEFAULT IS NULL AND EXTRA = 'auto_increment') OR (COLUMN_NAME IN ('question_id', 'created_by') AND DATA_TYPE = 'bigint' AND COLUMN_TYPE = 'bigint unsigned' AND IS_NULLABLE = 'NO' AND COLUMN_DEFAULT IS NULL) OR (COLUMN_NAME IN ('category_id', 'concept_id', 'regulation_id', 'regulation_version_id', 'approved_by', 'reviewed_by') AND DATA_TYPE = 'bigint' AND COLUMN_TYPE = 'bigint unsigned' AND IS_NULLABLE = 'YES' AND COLUMN_DEFAULT IS NULL) OR (COLUMN_NAME IN ('source_page_group', 'source_page_start', 'source_page_end') AND DATA_TYPE = 'int' AND COLUMN_TYPE = 'int unsigned' AND IS_NULLABLE = 'YES' AND COLUMN_DEFAULT IS NULL) OR (COLUMN_NAME = 'revision' AND DATA_TYPE = 'int' AND COLUMN_TYPE = 'int unsigned' AND IS_NULLABLE = 'NO' AND COLUMN_DEFAULT IS NULL) OR (COLUMN_NAME = 'difficulty' AND DATA_TYPE = 'varchar' AND COLUMN_TYPE = 'varchar(16)' AND IS_NULLABLE = 'YES' AND COLUMN_DEFAULT IS NULL) OR (COLUMN_NAME IN ('type', 'source') AND DATA_TYPE = 'varchar' AND COLUMN_TYPE = 'varchar(16)' AND IS_NULLABLE = 'NO' AND COLUMN_DEFAULT IS NULL) OR (COLUMN_NAME = 'status' AND DATA_TYPE = 'varchar' AND COLUMN_TYPE = 'varchar(16)' AND IS_NULLABLE = 'NO' AND COLUMN_DEFAULT = 'pending') OR (COLUMN_NAME = 'stem' AND DATA_TYPE = 'text' AND COLUMN_TYPE = 'text' AND IS_NULLABLE = 'NO' AND COLUMN_DEFAULT IS NULL) OR (COLUMN_NAME IN ('options', 'answer') AND DATA_TYPE = 'json' AND COLUMN_TYPE = 'json' AND IS_NULLABLE = 'NO' AND COLUMN_DEFAULT IS NULL) OR (COLUMN_NAME = 'analysis' AND DATA_TYPE = 'text' AND COLUMN_TYPE = 'text' AND IS_NULLABLE = 'YES' AND COLUMN_DEFAULT IS NULL) OR (COLUMN_NAME = 'score_cents' AND DATA_TYPE = 'int' AND COLUMN_TYPE = 'int unsigned' AND IS_NULLABLE = 'NO' AND COLUMN_DEFAULT IS NULL) OR (COLUMN_NAME IN ('approved_at', 'reviewed_at', 'legacy_captured_at') AND DATA_TYPE = 'datetime' AND COLUMN_TYPE = 'datetime(3)' AND IS_NULLABLE = 'YES' AND COLUMN_DEFAULT IS NULL) OR (COLUMN_NAME = 'review_reason' AND DATA_TYPE = 'varchar' AND COLUMN_TYPE = 'varchar(1000)' AND IS_NULLABLE = 'YES' AND COLUMN_DEFAULT IS NULL) OR (COLUMN_NAME = 'created_at' AND DATA_TYPE = 'datetime' AND COLUMN_TYPE = 'datetime(3)' AND IS_NULLABLE = 'NO' AND COLUMN_DEFAULT = 'CURRENT_TIMESTAMP(3)' AND EXTRA = 'DEFAULT_GENERATED'))) = 27 AND (SELECT COUNT(*) FROM INFORMATION_SCHEMA.STATISTICS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'question_version') = 8 AND (SELECT COUNT(*) FROM INFORMATION_SCHEMA.STATISTICS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'question_version' AND ((INDEX_NAME = 'PRIMARY' AND NON_UNIQUE = 0 AND SEQ_IN_INDEX = 1 AND COLUMN_NAME = 'id' AND INDEX_TYPE = 'BTREE' AND SUB_PART IS NULL) OR (INDEX_NAME = 'uk_question_version_revision' AND NON_UNIQUE = 0 AND SEQ_IN_INDEX = 1 AND COLUMN_NAME = 'question_id' AND INDEX_TYPE = 'BTREE' AND SUB_PART IS NULL) OR (INDEX_NAME = 'uk_question_version_revision' AND NON_UNIQUE = 0 AND SEQ_IN_INDEX = 2 AND COLUMN_NAME = 'revision' AND INDEX_TYPE = 'BTREE' AND SUB_PART IS NULL) OR (INDEX_NAME = 'idx_question_version_candidate' AND NON_UNIQUE = 1 AND SEQ_IN_INDEX = 1 AND COLUMN_NAME = 'category_id' AND INDEX_TYPE = 'BTREE' AND SUB_PART IS NULL) OR (INDEX_NAME = 'idx_question_version_candidate' AND NON_UNIQUE = 1 AND SEQ_IN_INDEX = 2 AND COLUMN_NAME = 'type' AND INDEX_TYPE = 'BTREE' AND SUB_PART IS NULL) OR (INDEX_NAME = 'idx_question_version_candidate' AND NON_UNIQUE = 1 AND SEQ_IN_INDEX = 3 AND COLUMN_NAME = 'difficulty' AND INDEX_TYPE = 'BTREE' AND SUB_PART IS NULL) OR (INDEX_NAME = 'idx_question_version_candidate' AND NON_UNIQUE = 1 AND SEQ_IN_INDEX = 4 AND COLUMN_NAME = 'status' AND INDEX_TYPE = 'BTREE' AND SUB_PART IS NULL) OR (INDEX_NAME = 'idx_question_version_regulation' AND NON_UNIQUE = 1 AND SEQ_IN_INDEX = 1 AND COLUMN_NAME = 'regulation_id' AND INDEX_TYPE = 'BTREE' AND SUB_PART IS NULL))) = 8 THEN 1 ELSE 0 END AS complete;
ALTER TABLE question_version DROP COLUMN rubric, MODIFY COLUMN type VARCHAR(16) NOT NULL COMMENT 'single / multiple / judgment';

-- @step objective_answer_columns
-- @replaces-check 010_answers/extend_exam_answer_draft
-- @check SELECT CASE WHEN (SELECT COUNT(*) FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'exam_answer') = 9 AND (SELECT COUNT(*) FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'exam_answer' AND ((COLUMN_NAME = 'record_question_id' AND COLUMN_TYPE = 'bigint unsigned' AND IS_NULLABLE = 'YES' AND COLUMN_DEFAULT IS NULL) OR (COLUMN_NAME = 'gained_score' AND COLUMN_TYPE = 'decimal(5,2)' AND IS_NULLABLE = 'YES' AND COLUMN_DEFAULT IS NULL) OR (COLUMN_NAME = 'updated_at' AND COLUMN_TYPE = 'datetime(3)' AND IS_NULLABLE = 'NO' AND COLUMN_DEFAULT = 'CURRENT_TIMESTAMP(3)' AND EXTRA = 'DEFAULT_GENERATED on update CURRENT_TIMESTAMP(3)'))) = 3 THEN 1 ELSE 0 END AS complete;
ALTER TABLE exam_answer DROP COLUMN asset_ids, DROP COLUMN comment, DROP COLUMN grading_version, MODIFY COLUMN gained_score DECIMAL(5,2) NULL DEFAULT NULL COMMENT '客观题自动得分；未交卷为 NULL';

-- @step objective_record_columns
-- @replaces-check 010_answers/extend_exam_record_submission
-- @check SELECT CASE WHEN (SELECT COUNT(*) FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'exam_record' AND ((COLUMN_NAME = 'id' AND DATA_TYPE = 'bigint' AND COLUMN_TYPE = 'bigint unsigned' AND IS_NULLABLE = 'NO' AND COLUMN_DEFAULT IS NULL AND EXTRA = 'auto_increment') OR (COLUMN_NAME IN ('paper_id', 'user_id') AND DATA_TYPE = 'bigint' AND COLUMN_TYPE = 'bigint unsigned' AND IS_NULLABLE = 'NO' AND COLUMN_DEFAULT IS NULL AND EXTRA = '') OR (COLUMN_NAME IN ('regulation_id', 'assignment_id', 'active_assignment_id', 'release_id', 'category_id') AND DATA_TYPE = 'bigint' AND COLUMN_TYPE = 'bigint unsigned' AND IS_NULLABLE = 'YES' AND COLUMN_DEFAULT IS NULL AND EXTRA = '') OR (COLUMN_NAME IN ('source', 'difficulty') AND DATA_TYPE = 'varchar' AND COLUMN_TYPE = 'varchar(16)' AND IS_NULLABLE = 'YES' AND COLUMN_DEFAULT IS NULL AND EXTRA = '') OR (COLUMN_NAME = 'rule_snapshot' AND DATA_TYPE = 'json' AND COLUMN_TYPE = 'json' AND IS_NULLABLE = 'YES' AND COLUMN_DEFAULT IS NULL AND EXTRA = '') OR (COLUMN_NAME = 'snapshot_origin' AND DATA_TYPE = 'varchar' AND COLUMN_TYPE = 'varchar(32)' AND IS_NULLABLE = 'NO' AND COLUMN_DEFAULT = 'legacy_unavailable' AND EXTRA = '') OR (COLUMN_NAME = 'attempt_no' AND DATA_TYPE = 'int' AND COLUMN_TYPE = 'int' AND IS_NULLABLE = 'NO' AND COLUMN_DEFAULT = '1' AND EXTRA = '') OR (COLUMN_NAME = 'status' AND DATA_TYPE = 'varchar' AND COLUMN_TYPE = 'varchar(16)' AND IS_NULLABLE = 'NO' AND COLUMN_DEFAULT = 'in_progress' AND EXTRA = '') OR (COLUMN_NAME = 'score' AND DATA_TYPE = 'decimal' AND COLUMN_TYPE = 'decimal(5,2)' AND IS_NULLABLE = 'YES' AND COLUMN_DEFAULT IS NULL AND EXTRA = '') OR (COLUMN_NAME IN ('started_at', 'deadline_at') AND DATA_TYPE = 'datetime' AND COLUMN_TYPE = 'datetime(3)' AND IS_NULLABLE = 'NO' AND COLUMN_DEFAULT IS NULL AND EXTRA = '') OR (COLUMN_NAME IN ('submitted_at', 'draft_saved_at', 'graded_at') AND DATA_TYPE = 'datetime' AND COLUMN_TYPE = 'datetime(3)' AND IS_NULLABLE = 'YES' AND COLUMN_DEFAULT IS NULL AND EXTRA = '') OR (COLUMN_NAME = 'draft_revision' AND DATA_TYPE = 'int' AND COLUMN_TYPE = 'int unsigned' AND IS_NULLABLE = 'NO' AND COLUMN_DEFAULT = '0' AND EXTRA = '') OR (COLUMN_NAME = 'draft_payload_hash' AND DATA_TYPE = 'char' AND COLUMN_TYPE = 'char(64)' AND IS_NULLABLE = 'YES' AND COLUMN_DEFAULT IS NULL AND EXTRA = '') OR (COLUMN_NAME = 'submission_method' AND DATA_TYPE = 'varchar' AND COLUMN_TYPE = 'varchar(16)' AND IS_NULLABLE = 'YES' AND COLUMN_DEFAULT IS NULL AND EXTRA = '') OR (COLUMN_NAME = 'grading_state' AND DATA_TYPE = 'varchar' AND COLUMN_TYPE = 'varchar(32)' AND IS_NULLABLE = 'NO' AND COLUMN_DEFAULT = 'not_submitted' AND EXTRA = '') OR (COLUMN_NAME = 'created_at' AND DATA_TYPE = 'datetime' AND COLUMN_TYPE = 'datetime(3)' AND IS_NULLABLE = 'NO' AND COLUMN_DEFAULT = 'CURRENT_TIMESTAMP(3)' AND EXTRA = 'DEFAULT_GENERATED') OR (COLUMN_NAME = 'updated_at' AND DATA_TYPE = 'datetime' AND COLUMN_TYPE = 'datetime(3)' AND IS_NULLABLE = 'NO' AND COLUMN_DEFAULT = 'CURRENT_TIMESTAMP(3)' AND EXTRA = 'DEFAULT_GENERATED on update CURRENT_TIMESTAMP(3)'))) = 26 AND (SELECT COUNT(*) FROM INFORMATION_SCHEMA.STATISTICS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'exam_record' AND INDEX_NAME = 'PRIMARY') = 1 AND (SELECT COUNT(*) FROM INFORMATION_SCHEMA.STATISTICS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'exam_record' AND INDEX_NAME = 'PRIMARY' AND NON_UNIQUE = 0 AND SEQ_IN_INDEX = 1 AND COLUMN_NAME = 'id' AND INDEX_TYPE = 'BTREE' AND SUB_PART IS NULL) = 1 AND (SELECT COUNT(*) FROM INFORMATION_SCHEMA.STATISTICS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'exam_record' AND INDEX_NAME = 'uk_paper_user_attempt') = 3 AND (SELECT COUNT(*) FROM INFORMATION_SCHEMA.STATISTICS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'exam_record' AND INDEX_NAME = 'uk_paper_user_attempt' AND NON_UNIQUE = 0 AND ((SEQ_IN_INDEX = 1 AND COLUMN_NAME = 'paper_id') OR (SEQ_IN_INDEX = 2 AND COLUMN_NAME = 'user_id') OR (SEQ_IN_INDEX = 3 AND COLUMN_NAME = 'attempt_no')) AND INDEX_TYPE = 'BTREE' AND SUB_PART IS NULL) = 3 AND (SELECT COUNT(*) FROM INFORMATION_SCHEMA.STATISTICS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'exam_record' AND INDEX_NAME = 'uk_assignment_attempt') = 2 AND (SELECT COUNT(*) FROM INFORMATION_SCHEMA.STATISTICS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'exam_record' AND INDEX_NAME = 'uk_assignment_attempt' AND NON_UNIQUE = 0 AND ((SEQ_IN_INDEX = 1 AND COLUMN_NAME = 'assignment_id') OR (SEQ_IN_INDEX = 2 AND COLUMN_NAME = 'attempt_no')) AND INDEX_TYPE = 'BTREE' AND SUB_PART IS NULL) = 2 AND (SELECT COUNT(*) FROM INFORMATION_SCHEMA.STATISTICS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'exam_record' AND INDEX_NAME = 'uk_active_assignment') = 1 AND (SELECT COUNT(*) FROM INFORMATION_SCHEMA.STATISTICS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'exam_record' AND INDEX_NAME = 'uk_active_assignment' AND NON_UNIQUE = 0 AND SEQ_IN_INDEX = 1 AND COLUMN_NAME = 'active_assignment_id' AND INDEX_TYPE = 'BTREE' AND SUB_PART IS NULL) = 1 AND (SELECT COUNT(*) FROM INFORMATION_SCHEMA.STATISTICS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'exam_record' AND INDEX_NAME = 'idx_user_paper_status') = 3 AND (SELECT COUNT(*) FROM INFORMATION_SCHEMA.STATISTICS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'exam_record' AND INDEX_NAME = 'idx_user_paper_status' AND NON_UNIQUE = 1 AND ((SEQ_IN_INDEX = 1 AND COLUMN_NAME = 'user_id') OR (SEQ_IN_INDEX = 2 AND COLUMN_NAME = 'paper_id') OR (SEQ_IN_INDEX = 3 AND COLUMN_NAME = 'status')) AND INDEX_TYPE = 'BTREE' AND SUB_PART IS NULL) = 3 AND (SELECT COUNT(*) FROM INFORMATION_SCHEMA.STATISTICS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'exam_record' AND INDEX_NAME = 'idx_regulation_status') = 2 AND (SELECT COUNT(*) FROM INFORMATION_SCHEMA.STATISTICS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'exam_record' AND INDEX_NAME = 'idx_regulation_status' AND NON_UNIQUE = 1 AND ((SEQ_IN_INDEX = 1 AND COLUMN_NAME = 'regulation_id') OR (SEQ_IN_INDEX = 2 AND COLUMN_NAME = 'status')) AND INDEX_TYPE = 'BTREE' AND SUB_PART IS NULL) = 2 AND (SELECT COUNT(*) FROM INFORMATION_SCHEMA.STATISTICS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'exam_record' AND INDEX_NAME = 'idx_paper_status') = 2 AND (SELECT COUNT(*) FROM INFORMATION_SCHEMA.STATISTICS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'exam_record' AND INDEX_NAME = 'idx_paper_status' AND NON_UNIQUE = 1 AND ((SEQ_IN_INDEX = 1 AND COLUMN_NAME = 'paper_id') OR (SEQ_IN_INDEX = 2 AND COLUMN_NAME = 'status')) AND INDEX_TYPE = 'BTREE' AND SUB_PART IS NULL) = 2 AND (SELECT COUNT(*) FROM INFORMATION_SCHEMA.STATISTICS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'exam_record' AND INDEX_NAME = 'idx_status_deadline') = 2 AND (SELECT COUNT(*) FROM INFORMATION_SCHEMA.STATISTICS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'exam_record' AND INDEX_NAME = 'idx_status_deadline' AND NON_UNIQUE = 1 AND ((SEQ_IN_INDEX = 1 AND COLUMN_NAME = 'status') OR (SEQ_IN_INDEX = 2 AND COLUMN_NAME = 'deadline_at')) AND INDEX_TYPE = 'BTREE' AND SUB_PART IS NULL) = 2 AND (SELECT COUNT(*) FROM INFORMATION_SCHEMA.STATISTICS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'exam_record' AND INDEX_NAME = 'idx_exam_record_release') = 1 AND (SELECT COUNT(*) FROM INFORMATION_SCHEMA.STATISTICS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'exam_record' AND INDEX_NAME = 'idx_exam_record_release' AND NON_UNIQUE = 1 AND SEQ_IN_INDEX = 1 AND COLUMN_NAME = 'release_id' AND INDEX_TYPE = 'BTREE' AND SUB_PART IS NULL) = 1 AND (SELECT COUNT(*) FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'exam_record' AND COLUMN_NAME IN ('last_heartbeat_at','device_summary','grading_revision','switch_count')) = 0 THEN 1 ELSE 0 END AS complete;
ALTER TABLE exam_record DROP COLUMN last_heartbeat_at, DROP COLUMN device_summary, DROP COLUMN switch_count, DROP COLUMN grading_revision, MODIFY COLUMN grading_state VARCHAR(32) NOT NULL DEFAULT 'not_submitted' COMMENT 'not_submitted / finalized', MODIFY COLUMN graded_at DATETIME(3) NULL COMMENT '最终结算时间；历史未知为 NULL';

